G=load(); print(sorted(G))
# general solver: marker = least frequent non-bg color (2x2 square in d5). noise = next color.
# Paint all 4 dihedral images of every noise cell about marker center; keep markers & non-bg cells.
def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    colors=sorted([c for c in cnt if c!=bg],key=lambda c:cnt[c])
    mkcol,ncol=colors[0],colors[1]
    mr=sum(a for a,b in [(r,c) for r in range(H) for c in range(W) if g[r][c]==mkcol])/4
    mc=sum(b for a,b in [(r,c) for r in range(H) for c in range(W) if g[r][c]==mkcol])/4
    out=[row[:] for row in g]
    imgs=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==ncol:
                pr,pc=r,c
                # four transforms
                for dr,dc in [(0,0),(1,1),(-1,1),(-1,-1)]:
                    pr2,pc2=int(round(dr*2*mr+r)),int(round(dc*2*mc+c))
                    imgs.append((pr2,pc2))
                # add identity too (already present)
    # careful: build transforms explicitly
    trans=[(r,c),(2*mr-r,c),(r,2*mc-c),(2*mr-r,2*mc-c)]
    for r in range(H):
        for c in range(W):
            if g[r][c]==ncol:
                for pr,pc in trans:
                    if 0<=pr<H and 0<=pc<W and out[pr][pc]==bg:
                        out[pr][pc]=ncol
    return out
