def f(g, overwrite=True):
    H,W=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    cols=sorted([c for c in cnt if c!=bg],key=lambda c:cnt[c])
    mkcol,ncol=cols[0],cols[1]
    marks=[(r,c) for r in range(H) for c in range(W) if g[r][c]==mkcol]
    mr=sum(a for a,b in marks)/len(marks); mc=sum(b for a,b in marks)/len(marks)
