gi6,go6=G['Demo pair 6 input'],G['Demo pair 6 output']
test=G['Test input']

def f(gi):
    h,w=len(gi),len(gi[0])
    bg=Counter(x for r in gi for x in r).most_common(1)[0][0]
    out=[[gi[i][j] for j in range(w)] for i in range(h)]
    for c in list(set(x for r in gi for x in r)-{bg}):
        cs=[(i,j) for i,r in enumerate(gi) for j,x in enumerate(r) if x==c]
        rs={i for i,_ in cs}; cc={j for _,j in cs}
        if len(cs)==4 and len(rs)==2 and len(cc)==2 and max(rs)-min(rs)==1 and max(cc)-min(cc)==1:
            pi=(min(rs)+max(rs))/2; pj=(min(cc)+max(cc))/2
            for i in range(h):
                for j in range(w):
                    if gi[i][j]!=bg and gi[i][j]!=c:
                        for ni,nj in [(round(2*pi-i),j),(i,round(2*pj-j)),(round(2*pi-i),round(2*pj-j))]:
                            if 0<=ni<h and 0<=nj<w: out[ni][nj]=gi[i][j]
    return out

print('d5',f(gi5)==go5,'d6',f(gi6)==go6)
res=f(test)
print(json.dumps(res))
